cache.cb5538bd4478c6acffad9f06b3a9bb71e3285cc9:
{
  "product": {
    "title_es": "Guirnalda de Piñas Naturales con Cascabel y Lazo para Decoración Navideña",
    "description_es": "Añade un toque rústico y festivo a tu hogar con esta guirnalda decorativa. Elaborada con piñas naturales, incluye detalles como lazos elegantes y cascabeles que aportan carácter navideño. Ideal para colgar en puertas, paredes o ventanas. Su diseño versátil combina bien con otros adornos tradicionales. Peso ligero de 60g por unidad, fácil de instalar sin herramientas. Perfecta para crear ambientes acogedores durante las fiestas. Disponible en varios modelos (A01-C05) para adaptarse a diferentes estilos de decoración interior.",
    "title_pt": "Guirlanda de Pinhas Naturais com Sino e Laço para Decoração Natalina",
    "description_pt": "Decore seu ambiente com esta guirlanda feita de pinhas naturais, perfeita para o Natal. Acompanha laços e sinos que trazem charme e tradição à decoração. Leve (60g), é ideal para pendurar em portas, janelas ou paredes sem esforço. O design rústico combina com diversos estilos de interiores. Disponível em múltiplos modelos (A01 a C05) para atender diferentes preferências estéticas. Fácil de manusear e reutilizar ano após ano. Uma opção econômica e eficaz para dar vida às celebrações natalinas no lar.",
    "attributes": [
      {
        "name": "Material",
        "value_name": "Natural Pinecones"
      },
      {
        "name": "Weight",
        "value_name": "60g"
      }
    ],
    "brand_terms": [],
    "product_type_en": "Christmas Decoration Wreath"
  }
}

